INSERT INTO news_post (post_type, date, title, text, rating, author_id) VALUES ('A', '2026-09-01 00:00', 'Статья 1', 'Статья 1 Одним из главных новшеств является улучшенная камера с возможностью записи видео в формате 4K и функцией ночной съемки, которая значительно улучшит качество фотографий даже в условиях низкой освещенности. Кроме того, смартфон оснащен более мощным процессором, что обеспечивает быструю и плавную работу приложений.', 1, 2);
